52	interface Props {
53	  room: RoomInterface | undefined;
54	  roomId: string;
55	}
56	
57	const TIMELINE_PAGE_SIZE = 20;
58	const ENABLE_TIMELINE_DEBUG = __DEV__;
59	
60	export const useRoomTimeline = ({ room, roomId }: Props) => {
61	  const [events, setEvents] = useState<EventTimelineItem[]>([]);
62	  const [loadingMessage, setLoadingMessage] = useState(true);
63	  /** Track processed verification request IDs to avoid duplicates */
64	  // const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
65	  const [refreshing, setRefreshing] = useState(false);
66	  const [updateTrigger, setUpdateTrigger] = useState(0);
67	  const eventIdsRef = useRef<Set<string>>(new Set());
68	  const timelineItemsRef = useRef<Array<EventTimelineItem | null>>([]);
69	  const timelineRef = useRef<TimelineInterface | null>(null);
70	  const isPaginatingRef = useRef(false);
71	  // const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
72	  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
73	  const [isDirect, setIsDirect] = useState(false);
74	  /** FIFO queue of transactionIds for in-flight own messages, used to match the final echo Set diff */
75	  const pendingTransactionIdsQueue = useRef<string[]>([]);
76	
77	  const toEventItem = (item: TimelineItemInterface): EventTimelineItem | null =>
78	    item.asEvent() ?? null;
79	
80	  const rebuildEventsFromTimelineItems = useCallback(() => {
81	    const seenIds = new Set<string>();
82	    const nextEvents: EventTimelineItem[] = [];
83	
84	    for (const item of timelineItemsRef.current) {
85	      if (!item) continue;
86	      const key = getItemUniqueKey(item);
87	      if (key) {
88	        if (seenIds.has(key)) continue;
89	        seenIds.add(key);
90	      }
91	      nextEvents.push(item);
92	    }
93	
94	    eventIdsRef.current = seenIds;
95	    setEvents(nextEvents);
96	  }, []);
97	
98	  //Remove for now verification requests
99	  // const handleVerificationRequest = (info: {
100	  //   senderId: string;
101	  //   flowId: string;
102	  // }) => {
103	  //   setVerificationStatus("incomingRequest");
104	  //   NavigationContainerRef.navigate("verifyUser", {
105	  //     userId: info.senderId,
106	  //     flowId: info.flowId,
107	  //   });
108	  // };
109	
110	  // const checkForVerificationRequests = useCallback(
111	  //   (incoming: EventTimelineItem[]) => {
112	  //     for (const event of incoming) {
113	  //       if (event.isOwn) continue;
114	
115	  //       if (
116	  //         !isVerificationRequest(event) ||
117	  //         !isRecentVerificationRequest(event)
118	  //       ) {
119	  //         continue;
120	  //       }
121	
122	  //       const flowId = getEventId(event);
123	  //       if (!flowId) continue;
124	
125	  //       if (processedVerificationRequestsRef.current.has(flowId)) continue;
126	
127	  //       processedVerificationRequestsRef.current.add(flowId);
128	
129	  //       handleVerificationRequest({
130	  //         senderId: event.sender,
131	  //         flowId,
132	  //       });
133	
134	  //       // Only handle one at a time
135	  //       break;
136	  //     }
137	  //   },
138	  //   [],
139	  // );
140	
141	  const markAsRead = useCallback(async () => {
142	    if (!room) return;
143	    if (AppState.currentState !== "active") return;
144	
145	    try {
146	      await room.markAsRead(ReceiptType.Read);
147	    } catch (error) {
148	      console.error("Failed to mark room as read:", error);
149	    }
150	  }, [room]);
151	
152	  const loadMoreMessages = useCallback(async () => {
153	    if (!timelineRef.current) return;
154	
155	    isPaginatingRef.current = true;
156	    setRefreshing(true);
157	
158	    try {
159	      await timelineRef.current.paginateBackwards(TIMELINE_PAGE_SIZE);
160	    } catch (error) {
161	      console.error("Failed to load more messages:", error);
162	    } finally {
163	      setRefreshing(false);
164	      isPaginatingRef.current = false;
165	    }
166	  }, []);
167	
168	  useEffect(() => {
169	    if (!room) return;
170	    setPinnedEventIds([]);
171	    TimelineService.getPinnedEventIds(roomId)
172	      .then(setPinnedEventIds)
173	      .catch(console.error);
174	  }, [room, roomId, setPinnedEventIds]);
175	
176	  useEffect(() => {
177	    if (!room) return;
178	
179	    // Reset state when room changes
180	    setLoadingMessage(true);
181	    setEvents([]);
182	    timelineItemsRef.current = [];
183	    eventIdsRef.current.clear();
184	    pendingTransactionIdsQueue.current = [];
185	
186	    let timelineListenerHandle: TaskHandleInterface | null = null;
187	    let isDisposed = false;
188	
189	    const initRoomTimeline = async () => {
190	      try {
191	        const timeline = await room.timelineWithConfiguration({
192	          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
193	          filter: new TimelineFilter.All(),
194	          internalIdPrefix: undefined,
195	          dateDividerMode: DateDividerMode.Daily,
196	          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
197	          reportUtds: false,
198	        });
199	
200	        // Store timeline in ref for reuse in pagination
201	        timelineRef.current = timeline;
202	
203	        // Set up listener BEFORE paginateBackwards so the SDK's initial
204	        // cached diffs (from SQLite) are received immediately — no network needed.
205	        let receivedInitialItems = false;
206	
207	        // Set up timeline listener for real-time updates
208	        timelineListenerHandle = await timeline.addListener({
209	          onUpdate: (diffs) => {
210	            // Trigger re-render to update read receipts and other event properties
211	            setUpdateTrigger((prev) => prev + 1);
212	
213	            const beforeCount = timelineItemsRef.current.length;
214	            diffs.forEach((diff) => {
215	              const change = diff.tag;
216	              const timelineItems = timelineItemsRef.current;
217	              switch (change) {
218	                case TimelineDiff_Tags.Append: {
219	                  if (diff.inner.values.length > 0) {
220	                    timelineItems.push(...diff.inner.values.map(toEventItem));
221	                  }
222	                  break;
223	                }
224	                case TimelineDiff_Tags.Insert: {
225	                  const { index, value } = diff.inner;
226	                  timelineItems.splice(index, 0, toEventItem(value));
227	                  break;
228	                }
229	                case TimelineDiff_Tags.Set: {
230	                  const { index, value } = diff.inner;
231	                  const ev = toEventItem(value);
232	                  timelineItems[index] = ev;
233	
234	                  // transactionId -> eventId transition can arrive in an order where
235	                  // a stale local echo still exists elsewhere in the list.
236	                  if (
237	                    ev?.isOwn &&
238	                    !ev.localSendState &&
239	                    pendingTransactionIdsQueue.current.length > 0
240	                  ) {
241	                    const txId = pendingTransactionIdsQueue.current.shift();
242	                    if (txId) {
243	                      const txIndex = timelineItems.findIndex((item) => {
244	                        if (!item) return false;
245	                        return getItemUniqueKey(item) === txId;
246	                      });
247	                      if (txIndex !== -1) {
248	                        timelineItems[txIndex] = ev;
249	                      }
250	                    }
251	                  }
252	                  break;
253	                }
254	                case TimelineDiff_Tags.Remove: {
255	                  const { index: removeIndex } = diff.inner;
256	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
257	                    timelineItems.splice(removeIndex, 1);
258	                  }
259	                  break;
260	                }
261	                case TimelineDiff_Tags.PushFront: {
262	                  const { value } = diff.inner;
263	                  timelineItems.unshift(toEventItem(value));
264	                  break;
265	                }
266	                case TimelineDiff_Tags.PushBack: {
267	                  const { value } = diff.inner;
268	                  const ev = toEventItem(value);
269	                  timelineItems.push(ev);
270	                  if (ev) {
271	                    const txId = getTransactionId(ev);
272	                    if (txId) {
273	                      pendingTransactionIdsQueue.current.push(txId);
274	                    }
275	                  }
276	                  break;
277	                }
278	                case TimelineDiff_Tags.PopFront: {
279	                  timelineItems.shift();
280	                  break;
281	                }
282	                case TimelineDiff_Tags.PopBack: {
283	                  timelineItems.pop();
284	                  break;
285	                }
286	                case TimelineDiff_Tags.Reset: {
287	                  const resetItems = diff.inner.values;
288	                  pendingTransactionIdsQueue.current = [];
289	                  timelineItemsRef.current = resetItems.map(toEventItem);
290	
291	                  const eventItems = timelineItemsRef.current.filter(
292	                    (i): i is EventTimelineItem => !!i,
293	                  );
294	                  pendingTransactionIdsQueue.current = eventItems
295	                    .map(getTransactionId)
296	                    .filter((id): id is string => !!id);
297	                  break;
298	                }
299	                case TimelineDiff_Tags.Truncate: {
300	                  const { length: cut } = diff.inner;
301	                  timelineItems.length = cut;
302	                  break;
303	                }
304	                case TimelineDiff_Tags.Clear: {
305	                  timelineItemsRef.current = [];
306	                  pendingTransactionIdsQueue.current = [];
307	                  eventIdsRef.current = new Set();
308	                  setEvents([]);
309	                  break;
310	                }
311	                default:
312	                  console.log("Unknown timeline change type:", change);
313	              }
314	            });
315	
316	            if (diffs.some((diff) => diff.tag !== TimelineDiff_Tags.Clear)) {
317	              rebuildEventsFromTimelineItems();
318	            }
319	
320	            if (ENABLE_TIMELINE_DEBUG) {
321	              const afterCount = timelineItemsRef.current.length;
322	              const tags = diffs.map((d) => d.tag).join(", ");
323	              console.log(
324	                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
325	              );
326	            }
327	
328	            // Hide loading spinner on first update (cached items from SQLite
329	            // or live items from network — whichever arrives first)
330	            if (!receivedInitialItems) {
331	              receivedInitialItems = true;
332	              setLoadingMessage(false);
333	            }
334	          },
335	        });
336	
337	        // Paginate after the listener is set up so events flow through it.
338	        // Don't await — cached messages are already visible; network results
339	        // will arrive as further diffs without blocking the UI.
340	        timeline
341	          .paginateBackwards(TIMELINE_PAGE_SIZE)
342	          .then(async () => {
343	            if (isDisposed) return;
344	            // If the cache only had a few items, paginate once more to
345	            // pull a full page from the network so the user sees recent history.
346	            if (timelineItemsRef.current.length < TIMELINE_PAGE_SIZE) {
347	              try {
348	                await timeline.paginateBackwards(TIMELINE_PAGE_SIZE);
349	              } catch {
350	                // best-effort — cached items are already visible
351	              }
352	            }
353	            setLoadingMessage(false);
354	          })
355	          .catch((error) => {
356	            if (isDisposed) return;
357	            // Offline or network error — user already sees cached messages
358	            console.warn("Failed to load initial messages:", error);
359	            setLoadingMessage(false);
360	          });
361	      } catch (error) {
362	        console.error("Failed to initialize room timeline:", error);
363	        offlineToastHelper("Failed to load the messages. Please try again.");
364	        NavigationContainerRef.goBack();
365	        return null;
366	      }
367	    };
368	
369	    initRoomTimeline();
370	
371	    return () => {
372	      isDisposed = true;
373	      timelineListenerHandle?.cancel?.();
374	      timelineRef.current = null;
375	      timelineItemsRef.current = [];
376	      isPaginatingRef.current = false;
377	      setRefreshing(false);
378	    };
379	  }, [rebuildEventsFromTimelineItems, room, roomId]);
380	
381	  useEffect(() => {
382	    markAsRead().catch(console.error);
383	    room?.isDirect().then(setIsDirect).catch(console.error);
384	  }, [room, markAsRead]);
385	
386	  return {
387	    events,
388	    loadingMessage,
389	    refreshing,
390	    timelineRef,
391	    isPaginatingRef,
392	    updateTrigger,
393	    isDirect,
394	    loadMoreMessages,
395	    markAsRead,
396	  };
397	};
